INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'JOBSEARCH-LLM-RERANK-1: qnfo-jobsearch has no AI step; add a reorder-only re-rank of the top matches',
 'Charter pillar: reach. The owner asked for an AI-powered job search; the matcher is deterministic keyword and cluster scoring and only 8 of 5,900 postings pass its gates. Doer: qnfo-code-orchestrator. Lever: after collectAndRank and before the per-company cap, ask a model through the qnfo-ai service binding (props caller qnfo-jobsearch, CLAUDE.md 1703, no key copy) to order the top 25 passing postings by fit to the claim ledger and give one sentence of reason. Hard limits: the model may only reorder and annotate; it must never write or change resume or note text (drafts stay assembled from the ledger and re-verified); a failed or empty answer leaves the deterministic order; the call is skipped while it would cost more than the cheapest Workers AI model (BUDGET-SOFT-ROUTE-1); reasons are stored in jobsearch_matches.why_json prefixed LLM:, and any text the model returns is passed through verify_freeform-style checks before it is shown (numbers and proper nouns must exist in the ledger or the posting). Add an offline test with a stub model. Definition of done: the version line carries JOBSEARCH-LLM-RERANK-1, the offline suite passes, and GET /api/ops stays ok after one hourly run.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-jobsearch/worker.js' || char(10) ||
 'code-anchor: return { kept, errors, excl, fetched, feeds: feedsList.length, feedResults };' || char(10) ||
 'code-probe: {"paths": ["qnfo-jobsearch/worker.js"], "contains": "JOBSEARCH-LLM-RERANK-1"}',
 'session', 'reliability', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'JOBSEARCH-LLM-RERANK-1:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'JOBSEARCH-SOURCES-1: qnfo-jobsearch reads 17 feeds and only 8 of 5,900 postings pass; add Dutch and EU sources and more employers',
 'Charter pillar: reach. Measured 2026-10-27: 5,900 postings from 17 feeds per run, 8 pass the gates, all tier B, most US on-site. The owner lives in Amsterdam and is open to any location, authorized in NL and US. Doer: qnfo-code-orchestrator. Lever: extend BOARDS in qnfo-jobsearch/worker.js with employers that hire research managers, applied AI, research-integrity and policy-research roles and publish a public ATS board (Greenhouse, Lever or Ashby slug) or an open feed: Dutch and EU public-sector research bodies, EU institutions, universities and research institutes with Ashby or Greenhouse boards, AI safety and governance organisations, and consultancies; add a DISPLAY name for each; keep ToS-clean sources only (no LinkedIn, no Indeed scraping); a board that returns 404 is removed rather than left failing (jobsearch_feeds already tracks the streak). Do not loosen any gate or the claim verifier to raise the pass count. Definition of done: the version line carries JOBSEARCH-SOURCES-1, GET /api/runs shows more feeds than 17 with none failing 3 runs in a row, and the offline suite passes.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-jobsearch/worker.js' || char(10) ||
 'code-anchor: const DISPLAY = { openai: "OpenAI", scaleai: "Scale AI",' || char(10) ||
 'code-probe: {"paths": ["qnfo-jobsearch/worker.js"], "contains": "JOBSEARCH-SOURCES-1"}',
 'session', 'reliability', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'JOBSEARCH-SOURCES-1:%' AND status = 'open');

INSERT INTO human_actions (slug, title, why, default_in_effect, action, url, sev, status, source, created_at, updated_at)
SELECT 'jobsearch-ledger-owner-answers', 'Two facts only you can state for the job search ledger: your US work-authorization basis and your NL permit type',
 'IDENTITY-BOUND: your immigration and citizenship status is personal data only you can state; the fleet cannot read it from any source and must not guess it. The job matcher flags roles as needing a visa or citizenship when it does not know. With these two answers it stops flagging roles you can take. Until you answer, nothing is blocked: US roles are flagged "owner status unverified" and non-NL Europe roles are flagged "employer-of-record unverified".',
 'The flags stay as they are and no role is dropped or assumed.',
 'Answer in the fleet prompt panel at https://fleet.qnfo.org in one message: "jobsearch ledger: US = citizen | permanent resident | work visa type; NL permit = type, and whether it lets you work in other EU states". The fleet files it as an issue and a code-task updates jobsearch/facts.json and the embedded ledger, then the card closes when the worker reports no open ledger questions.',
 'https://fleet.qnfo.org', 'low', 'open', 'session:JOBSEARCH-HANDOFF-1', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = 'jobsearch-ledger-owner-answers');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('owner-card-jobsearch-ledger', NULL, 'JOBSEARCH-HANDOFF-1', 'closes the human_actions card jobsearch-ledger-owner-answers when the worker reports no open ledger questions',
  'SELECT ''ok'' AS expected, CASE WHEN (SELECT v FROM jobsearch_meta WHERE k = ''ledger_open_questions'') IS NULL THEN ''pending: qnfo-jobsearch 1.2.1 has not recorded the open ledger questions yet'' WHEN CAST((SELECT v FROM jobsearch_meta WHERE k = ''ledger_open_questions'') AS INTEGER) = 0 THEN ''ok'' ELSE ''pending: '' || (SELECT v FROM jobsearch_meta WHERE k = ''ledger_open_questions'') || '' ledger question(s) still open'' END AS observed',
  'd1-query', 3, 'qnfo-cloud-ops', 1, 'active', 'owner-step', datetime('now'));

UPDATE session_records SET
  summary = summary || ' Closeout 2026-10-28: outcome measure added (jobsearch_events, /api/outcomes, metric with trigger); remaining work handed to server-side doers.',
  handoff_notes = 'HANDED OFF 2026-10-28, each with a doer and a closing probe: JS-5 jobs.q08.org (agent_issue DOMAIN-PLANE-1:jobs.q08.org, runtime-probe on /health); JS-6 AI re-rank (JOBSEARCH-LLM-RERANK-1, code-task, code-probe); JS-7 more sources (JOBSEARCH-SOURCES-1, code-task, code-probe); JS-8 owner answers (human_actions jobsearch-ledger-owner-answers with IDENTITY-BOUND line and contract owner-card-jobsearch-ledger); JS-9 weight tuning (metric trigger jobsearch_reply_rate_90d, starts when 10 applications are 21 days old). Declined by design: automatic sending to recruiters. The stop-hook fleet backlog (about 64 items) was never this session and stays with the fleet loops. Roadmap: roadmap_implementation source jobsearch-2026 (JS-1 to JS-9). Server-side operation needs no session: hourly cron, GET /api/ops, fm-jobsearch-* detectors.',
  execution_ratio = 0.62, total_tasks = 16, completed_tasks = 10, completed_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE session_id = 'session-jobsearch-1027';

